/bin/bash -lc 'set -e
pref="$HOME/.config/google-chrome/Default/Preferences"
backup="$pref.bak-before-dnt-$(date +%Y%m%d%H%M%S)"
cp "$pref" "$backup"
node -e '"'
const fs = require(\"fs\");
const path = process.argv[1];
const data = JSON.parse(fs.readFileSync(path, \"utf8\"));
data.enable_do_not_track = true;
fs.writeFileSync(path, JSON.stringify(data));
' \""'$pref"
node -e '"'const fs=require(\"fs\"); const p=process.argv[1]; const data=JSON.parse(fs.readFileSync(p,\"utf8\")); console.log(JSON.stringify({enable_do_not_track:data.enable_do_not_track}));' \""'$pref"'

