/bin/bash -lc "set -e
rm -f /tmp/chrome-dnt-header.txt
node -e '
const http = require(\"http\");
const fs = require(\"fs\");
const server = http.createServer((req, res) => {
  fs.writeFileSync(\"/tmp/chrome-dnt-header.txt\", String(req.headers.dnt || \"\"));
  res.end(\"DNT check complete\");
  server.close();
});
server.listen(8765, \"127.0.0.1\");
setTimeout(() => server.close(), 15000);
' >/tmp/chrome-dnt-server.log 2>&1 &
sleep 0.5
nohup google-chrome --remote-debugging-port=1337 http://127.0.0.1:8765/dnt-check >/tmp/chrome-dnt-launch.log 2>&1 &
for i in "'$(seq 1 40); do
  if [ -f /tmp/chrome-dnt-header.txt ]; then
    printf '"'DNT header: %s\\n' \""'$(cat /tmp/chrome-dnt-header.txt)"
    exit 0
  fi
  sleep 0.25
done
printf '"'DNT header: not captured\\n'
exit 1"

